import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function DashboardPage() {
  const navigate = useNavigate();

  const [metrics, setMetrics] = useState({
    progress: 0,
    tasks: 0,
    quiz: 0,
  });

  const [streak, setStreak] = useState(0);
  const [recommendation, setRecommendation] = useState("");
  const [domain, setDomain] = useState("");
  const [freeze, setFreeze] = useState(1);
  const [freezeUsedToday, setFreezeUsedToday] = useState(false);

  const currentDay = parseInt(localStorage.getItem("currentDay") || "1");

  useEffect(() => {
    const roadmapPlan = JSON.parse(localStorage.getItem("roadmapPlan") || "[]");
    const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
    const frozenDays = JSON.parse(localStorage.getItem("frozenDays") || "[]");

    const quizScore = parseInt(localStorage.getItem("quizScore") || "0");
    const totalQuestions = parseInt(localStorage.getItem("totalQuestions") || "1");

    const lastCompleted = parseInt(localStorage.getItem("lastCompletedCount") || "0");
    const lastTotal = parseInt(localStorage.getItem("lastTotalTasks") || "1");

    const selectedDomain = localStorage.getItem("selectedDomain") || "learning";
    setDomain(selectedDomain.replace(/-/g, " "));

    // 📊 METRICS
    const totalTasks = roadmapPlan.flat().length;
    const totalDays = Math.ceil(totalTasks / 4);

    const progress =
      totalDays > 0
        ? Math.round((completedDays.length / totalDays) * 100)
        : 0;

    const tasks =
      lastTotal > 0
        ? Math.round((lastCompleted / lastTotal) * 100)
        : 0;

    const quiz =
      totalQuestions > 0
        ? Math.round((quizScore / totalQuestions) * 100)
        : 0;

    // 🔥 STREAK
    let currentStreak = 0;

    for (let i = completedDays.length - 1; i >= 0; i--) {
      const expectedDay = currentDay - currentStreak - 1;

      if (
        completedDays.includes(expectedDay) ||
        frozenDays.includes(expectedDay)
      ) {
        currentStreak++;
      } else {
        break;
      }
    }

    setFreezeUsedToday(frozenDays.includes(currentDay));

    // 🤖 AI Recommendation
    const generateRecommendation = () => {
      if (tasks < 50) return "⚡ Focus on completing daily tasks consistently.";
      if (quiz < 60) return "🧠 Revise concepts and improve quiz accuracy.";
      if (progress > 80) return "🚀 You're doing great! Start building projects.";
      if (currentStreak < 3) return "🔥 Build your streak by learning daily.";
      return "👍 Keep going, you're making solid progress!";
    };

    setMetrics({ progress, tasks, quiz });
    setStreak(currentStreak);
    setRecommendation(generateRecommendation());

    const savedFreeze = parseInt(localStorage.getItem("freeze") || "1");
    setFreeze(savedFreeze);

  }, [currentDay]);

  return (
    <div className="space-y-8">

      {/* 🔥 TOP SECTION */}
      <div className="grid gap-6 xl:grid-cols-[1.6fr_1fr]">

        {/* LEFT */}
        <div className="rounded-[2rem] bg-slate-800 border border-slate-700 p-8 shadow-xl">
          <h2 className="text-2xl font-semibold text-white">Welcome back 👋</h2>
          <p className="mt-2 text-slate-400">
            Continue your {domain} journey and track your growth.
          </p>

          <div className="mt-6 grid gap-4 sm:grid-cols-3">
            {[
              { label: "Course completion", value: metrics.progress },
              { label: "Daily tasks", value: metrics.tasks },
              { label: "Quiz accuracy", value: metrics.quiz },
            ].map((item) => (
              <div key={item.label} className="rounded-xl bg-slate-700 p-5">
                <p className="text-sm text-slate-400">{item.label}</p>
                <p className="text-2xl font-bold text-white mt-2">
                  {item.value}%
                </p>
              </div>
            ))}
          </div>
        </div>

        {/* RIGHT */}
        <div className="rounded-[2rem] bg-slate-800 border border-slate-700 p-8 shadow-xl">
          <h3 className="text-lg text-slate-300">Next milestone</h3>

          <div className="mt-4 rounded-xl bg-slate-700 p-4">
            <p className="text-sm text-slate-400">Recommended focus</p>
            <p className="text-white mt-2">{recommendation}</p>
          </div>

          <button
            onClick={() => navigate("/roadmap")}
            className="mt-6 w-full rounded-full bg-gradient-to-r from-cyan-500 to-blue-600 py-3 text-white font-semibold shadow-lg hover:scale-[1.02] hover:shadow-cyan-500/30 transition-all"
          >
            View roadmap
          </button>
        </div>
      </div>

      {/* 🔹 MIDDLE SECTION */}
      <div className="grid gap-6 md:grid-cols-3">

        <div className="rounded-[2rem] bg-slate-800 border border-slate-700 p-6 shadow-xl">
          <h3 className="text-lg text-white">Fundamentals</h3>
          <p className="text-sm text-slate-400 mt-2">
            Strengthen your core subjects.
          </p>
          <button
            onClick={() => navigate("/fundamentals")}
            className="mt-4 px-4 py-2 rounded-full bg-purple-500 text-white text-sm font-medium shadow-md hover:bg-purple-600 hover:scale-[1.05] transition"
          >
            Go to fundamentals
          </button>
        </div>

        <div className="rounded-[2rem] bg-slate-800 border border-slate-700 p-6 shadow-xl">
          <h3 className="text-lg text-white">Role paths</h3>
          <p className="text-sm text-slate-400 mt-2">
            Explore domain-based learning.
          </p>
          <button
            onClick={() => navigate("/domains")}
            className="mt-4 px-4 py-2 rounded-full bg-blue-500 text-white text-sm font-medium shadow-md hover:bg-blue-600 hover:scale-[1.05] transition"
          >
            Choose domain
          </button>
        </div>

        <div className="rounded-[2rem] bg-slate-800 border border-slate-700 p-6 shadow-xl">
          <h3 className="text-lg text-white">Daily study</h3>
          <p className="text-sm text-slate-400 mt-2">
            Stay consistent with daily tasks.
          </p>
          <button
            onClick={() => navigate("/tasks")}
            className="mt-4 px-4 py-2 rounded-full bg-indigo-500 text-white text-sm font-medium shadow-md hover:bg-indigo-600 hover:scale-[1.05] transition"
          >
            Open tasks
          </button>
        </div>

      </div>

      {/* 📊 PROGRESS + STREAK */}
      <div className="grid gap-6 xl:grid-cols-[1.6fr_1fr]">

        {/* PROGRESS */}
        <div className="rounded-[2rem] bg-slate-800 border border-slate-700 p-8 shadow-xl">
          <h3 className="text-lg text-white">Weekly progress</h3>

          <div className="mt-6 space-y-5">
            {[
              { label: "Course completion", value: metrics.progress },
              { label: "Daily tasks", value: metrics.tasks },
              { label: "Quiz accuracy", value: metrics.quiz },
            ].map((item) => (
              <div key={item.label}>
                <div className="flex justify-between text-sm text-slate-300 mb-1">
                  <span>{item.label}</span>
                  <span>{item.value}%</span>
                </div>

                <div className="h-2 bg-slate-700 rounded-full">
                  <div
                    className="h-full bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-500 transition-all duration-1000"
                    style={{ width: `${item.value}%` }}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* 🔥 STREAK */}
        <div className="rounded-[2rem] bg-slate-800 border border-slate-700 p-8 shadow-xl">

          <h3 className="text-lg text-slate-300">Growth streak</h3>

          <div className="mt-6 flex items-center gap-4">

            <div
              className={`text-4xl ${
                freezeUsedToday ? "blue-flame" : "flame-animate"
              }`}
            >
              🔥
            </div>

            <div>
              <p className="text-4xl font-bold text-white">{streak} days</p>
              <p className="text-sm text-slate-400">Keep your streak alive!</p>
            </div>

          </div>

          <div className="mt-4">

            <p className="text-sm text-slate-400">
              ❄️ Freeze left:{" "}
              <span className="text-white font-semibold">{freeze}</span>
            </p>

            <button
              disabled={freeze === 0 || freezeUsedToday}
              onClick={() => {
                const frozenDays = JSON.parse(localStorage.getItem("frozenDays") || "[]");

                frozenDays.push(currentDay);
                localStorage.setItem("frozenDays", JSON.stringify(frozenDays));

                const newFreeze = freeze - 1;
                localStorage.setItem("freeze", newFreeze);

                setFreeze(newFreeze);
                setFreezeUsedToday(true);

                alert("❄️ Streak frozen for today!");
              }}
              className={`mt-3 w-full rounded-full py-2 text-sm font-semibold ${
                freeze === 0 || freezeUsedToday
                  ? "bg-slate-700 text-slate-400"
                  : "bg-blue-500 text-white hover:bg-blue-600 hover:scale-[1.02] transition"
              }`}
            >
              {freezeUsedToday ? "Freeze Used Today ❄️" : "Use Freeze ❄️"}
            </button>

          </div>

        </div>

      </div>

    </div>
  );
}
